package com.example.gameworkbench.service.impl;
import com.example.gameworkbench.analytics.PromptMetricRow; import com.example.gameworkbench.mapper.ModelCallMetricMapper; import org.junit.jupiter.api.Test; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*;
class PromptVersionAnalyticsServiceImplTest { @Test void excludesMockByDefaultAndUsesNearestRankP95(){var mapper=mock(ModelCallMetricMapper.class);var rows=new ArrayList<PromptMetricRow>();for(int i=1;i<=20;i++){var r=new PromptMetricRow();r.setPromptVersionId(1L);r.setMockState(i==1?"TRUE":"FALSE");r.setStatus("SUCCESS");r.setLatencyMs((long)i);rows.add(r);}when(mapper.selectAnalyticsRows(any(),any(),any(),any(),any())).thenReturn(rows);var value=new PromptVersionAnalyticsServiceImpl(mapper).metrics(1L,null,null,LocalDateTime.now().minusDays(1),LocalDateTime.now(),false).getFirst();assertThat(value.getCallCount()).isEqualTo(19);assertThat(value.getMockSampleCount()).isZero();assertThat(value.getP95LatencyMs()).isEqualTo(20L);}}
